1	use pacquet_config::Config;
2	use std::ffi::{OsStr, OsString};
3	
4	/// CLI overrides parsed from pnpm's `--config.<key>=<value>` dotted-key
5	/// syntax. Upstream pnpm uses [`npm-conf`](https://github.com/npm/npm-conf)
6	/// to translate each `--config.<key>=<value>` token into a runtime config
7	/// assignment that wins over `.npmrc` and `pnpm-workspace.yaml`; pacquet
8	/// mirrors that by stripping the same tokens out of argv before clap sees
9	/// them and re-applying them onto [`Config`] after the file-based layers
10	/// have run.
11	///
12	/// Unknown keys are accepted silently: pnpm exposes a long tail of config
13	/// keys, and erroring on an unrecognized one would break the moment pnpm
14	/// adds a new key that pacquet hasn't ported yet. The token has already
15	/// been honored by pnpm itself before delegation, so dropping it on
16	/// pacquet's side just means the pacquet leg falls back to the yaml/npmrc
17	/// value — never an incorrect override.
18	#[derive(Debug, Default)]
19	pub struct ConfigOverrides {
20	    registry: Option<String>,
21	}
22	
23	impl ConfigOverrides {
24	    /// Pull `--config.<key>=<value>` tokens out of `argv` and collect
25	    /// them. Returns the parsed overrides together with the remaining
26	    /// argv tokens (in their original order) for clap to parse.
27	    ///
28	    /// Malformed tokens — `--config.foo` with no `=`, or `--config.=value`
29	    /// with an empty key — are dropped: clap would reject `--config.*` as
30	    /// unknown anyway, and the dropped tokens carry no usable signal.
31	    pub fn extract<Argv>(argv: Argv) -> (Self, Vec<OsString>)
32	    where
33	        Argv: IntoIterator<Item = OsString>,
34	    {
35	        let mut overrides = Self::default();
36	        let mut remaining = Vec::new();
37	        for arg in argv {
38	            match classify(&arg) {
39	                ConfigToken::WellFormed { key, value } => overrides.set(key, value),
40	                ConfigToken::Malformed => {}
41	                ConfigToken::NotOurs => remaining.push(arg),
42	            }
43	        }
44	        (overrides, remaining)
45	    }
46	
47	    fn set(&mut self, key: &str, value: &str) {
48	        if key == "registry" {
49	            self.registry = Some(value.to_owned());
50	        }
51	    }
52	
53	    /// Layer the CLI overrides on top of a [`Config`] that has already
54	    /// been built from defaults, `.npmrc`, and `pnpm-workspace.yaml`.
55	    /// Mirrors pnpm 11's "CLI > yaml > .npmrc > defaults" precedence.
56	    pub fn apply(&self, config: &mut Config) {
57	        if let Some(registry) = &self.registry {
58	            config.registry.clone_from(registry);
59	        }
60	    }
61	}
62	
63	enum ConfigToken<'a> {
64	    WellFormed { key: &'a str, value: &'a str },
65	    Malformed,
66	    NotOurs,
67	}
68	
69	/// Decide whether an argv token belongs to the `--config.<key>=<value>`
70	/// family. Everything with a `--config.` prefix is claimed, so a typo
71	/// like `--config.foo` never escapes into clap's "unexpected argument"
72	/// path; non-prefixed tokens are returned untouched.
73	fn classify(arg: &OsStr) -> ConfigToken<'_> {
74	    let Some(rest) = arg.to_str().and_then(|arg| arg.strip_prefix("--config.")) else {
75	        return ConfigToken::NotOurs;
76	    };
77	    let Some((key, value)) = rest.split_once('=') else {
78	        return ConfigToken::Malformed;
79	    };
80	    if key.is_empty() {
81	        return ConfigToken::Malformed;
82	    }
83	    ConfigToken::WellFormed { key, value }
84	}
