/// every byte in the prefix region is ASCII (a non-ASCII byte can't be
/// ASCII-case-equal to an ASCII prefix byte), so `prefix.len()` is
/// guaranteed to land on a char boundary before we slice.
fn strip_prefix_ascii_ci<'a>(name: &'a str, prefix: &str) -> Option<&'a str> {
    let bytes = name.as_bytes();
    let prefix_bytes = prefix.as_bytes();
    if bytes.len() < prefix_bytes.len()
        || !bytes[..prefix_bytes.len()].eq_ignore_ascii_case(prefix_bytes)
    {
        return None;
    }
    Some(&name[prefix_bytes.len()..])
}

